def _stamp_utr_annotator_and_flag_backfill(apps, _schema_editor):
    """ Stamp the utr_annotator pin on the versions the scheduler can still match, from live settings.
        Left NULL while settings name the file, every run would fail with VEPVersionMismatchError and
        create_new_variant_annotation_version would mint a new version - a full re-annotation.

        A version that has annotated variants, at a columns_version / VEP the plugin's columns cover,
        holds them without UTRAnnotator - it is flagged for the backfill. HISTORICAL versions are left
        alone: nothing looks them up by config again. """
    VariantAnnotationVersion = apps.get_model("annotation", "VariantAnnotationVersion")
    AnnotationRangeLock = apps.get_model("annotation", "AnnotationRangeLock")
    for vav in VariantAnnotationVersion.objects.filter(status__in=["NEW", "ACTIVE"]):
        build_settings = settings.ANNOTATION.get(vav.genome_build_id)
        if build_settings is None:
            continue  # Build no longer configured on this deployment
        vav.utr_annotator = vep_component_version_kwargs(build_settings)["utr_annotator"]
        plugin_columns = vep_columns.filter_for(vep_plugin=VEPPlugin.UTR_ANNOTATOR,
                                                genome_build_name=vav.genome_build_id,
                                                columns_version=vav.columns_version,
                                                vep_version=vav.vep)
        has_annotation = AnnotationRangeLock.objects.filter(version=vav).exists()
        vav.backfilled_utr_annotator = not (vav.utr_annotator and plugin_columns and has_annotation)
        vav.save(update_fields=["utr_annotator", "backfilled_utr_annotator"])


